-- Transferencia de administración sin migrar de plataforma.
CREATE TABLE transition_parties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id)ON DELETE RESTRICT,transition_id uuid NOT NULL REFERENCES transitions(id)ON DELETE RESTRICT,party_type text NOT NULL CHECK(party_type IN('outgoing','incoming','community')),name text NOT NULL,email citext,user_id uuid REFERENCES app_users(id)ON DELETE SET NULL,status text NOT NULL DEFAULT 'invited' CHECK(status IN('invited','accepted','revoked')),accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transition_id,party_type));
CREATE TABLE transition_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id)ON DELETE RESTRICT,transition_id uuid NOT NULL REFERENCES transitions(id)ON DELETE RESTRICT,category text NOT NULL CHECK(category IN('documents','banking','contracts','keys','credentials','pending_cases','accounting','other')),title text NOT NULL,description text,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','delivered','accepted','reserved')),checksum char(64),delivered_by uuid REFERENCES app_users(id)ON DELETE SET NULL,delivered_at timestamptz,accepted_by uuid REFERENCES app_users(id)ON DELETE SET NULL,accepted_at timestamptz,reservation_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transition_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),community_id uuid NOT NULL REFERENCES communities(id)ON DELETE RESTRICT,transition_id uuid NOT NULL REFERENCES transitions(id)ON DELETE RESTRICT,event_type text NOT NULL,description text NOT NULL,actor_user_id uuid REFERENCES app_users(id)ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['transition_parties','transition_items','transition_events']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I FOR ALL TO comunidad_conecta_app USING(community_id=current_app_community_id())WITH CHECK(community_id=current_app_community_id())',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO comunidad_conecta_app',t);END LOOP;END$$;
CREATE INDEX transition_items_status_idx ON transition_items(community_id,transition_id,status);CREATE INDEX transition_events_idx ON transition_events(community_id,transition_id,created_at);
